import { focusRing } from "@/lib/beton/shared";
import { tv, type VariantProps } from "@/lib/beton/tv";

export const menubar = tv({
  slots: {
    root: "flex w-fit items-center gap-1 border-3 border-border bg-raised p-1 shadow-sm",
    trigger: [
      "flex min-h-11 cursor-pointer select-none items-center gap-2 border-3 border-transparent px-3",
      "font-display font-extrabold uppercase tracking-wide text-foreground",
      "hover:border-border data-popup-open:border-border data-popup-open:bg-secondary",
      "data-disabled:cursor-not-allowed data-disabled:text-disabled-foreground",
      focusRing,
    ],
  },
  variants: {
    size: {
      sm: { trigger: "text-xs" },
      md: { trigger: "text-sm" },
      lg: { trigger: "min-h-12 text-base" },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type MenubarVariants = VariantProps<typeof menubar>;

"use client";

import { Menubar as BaseMenubar } from "@base-ui/react/menubar";
import { Menu } from "@base-ui/react/menu";
import { menubar, type MenubarVariants } from "@/lib/beton/recipes/menubar.recipe";
import { createContext, useContext } from "react";
import { DropdownMenu } from "@/components/ui/beton/dropdown-menu";

const MenubarContext = createContext<NonNullable<MenubarVariants["size"]>>("md");

export interface MenubarProps extends Omit<BaseMenubar.Props, "className">, MenubarVariants {
  className?: string;
}

function MenubarRoot({ size = "md", className, ...props }: MenubarProps) {
  return (
    <MenubarContext.Provider value={size}>
      <BaseMenubar {...props} className={menubar({ size }).root({ class: className })} />
    </MenubarContext.Provider>
  );
}

export type MenubarMenuProps = Menu.Root.Props;

function MenubarMenu(props: MenubarMenuProps) {
  return <Menu.Root {...props} />;
}

export interface MenubarTriggerProps extends Omit<Menu.Trigger.Props, "className"> {
  className?: string;
}

function MenubarTrigger({ className, ...props }: MenubarTriggerProps) {
  const size = useContext(MenubarContext);
  return (
    <Menu.Trigger
      {...props}
      data-size={size}
      className={menubar({ size }).trigger({ class: className })}
    />
  );
}

/** A row of menus along the top of an application, as in a desktop app. */
export const Menubar = Object.assign(MenubarRoot, {
  Menu: MenubarMenu,
  Trigger: MenubarTrigger,
  Content: DropdownMenu.Content,
  Item: DropdownMenu.Item,
  Link: DropdownMenu.Link,
  CheckboxItem: DropdownMenu.CheckboxItem,
  RadioGroup: DropdownMenu.RadioGroup,
  RadioItem: DropdownMenu.RadioItem,
  Group: DropdownMenu.Group,
  GroupLabel: DropdownMenu.GroupLabel,
  Separator: DropdownMenu.Separator,
  Submenu: DropdownMenu.Submenu,
  SubmenuTrigger: DropdownMenu.SubmenuTrigger,
});
